<?php
require_once __DIR__ . '/_layout.php';if(!can('reports.view')&&!can('reports.financial')){http_response_code(403);exit('Not authorized.');}
$ids=currentAgencyIds();if(!$ids)$ids=[0];$agencyId=(int)($_GET['agency_id']??$ids[0]);requireAgencyAccess($agencyId);$requestedFrom=$_GET['from']??date('Y-m-01');$requestedTo=$_GET['to']??date('Y-m-t');$from=validDateValue($requestedFrom)?$requestedFrom:date('Y-m-01');$to=validDateValue($requestedTo)?$requestedTo:date('Y-m-t');$start=$from.' 00:00:00';$end=$to.' 23:59:59';
$summary=dbFetchOne("SELECT COALESCE(SUM(CASE WHEN p.status='paid' THEN p.amount ELSE 0 END),0) revenue,COUNT(DISTINCT r.id) reservations,COALESCE(AVG(r.rental_days),0) avg_duration,COALESCE(AVG(r.daily_price),0) avg_daily_rate FROM reservations r LEFT JOIN payments p ON p.reservation_id=r.id AND p.paid_at BETWEEN :start AND :end WHERE r.agency_id=:agency AND r.created_at BETWEEN :start2 AND :end2",['start'=>$start,'end'=>$end,'agency'=>$agencyId,'start2'=>$start,'end2'=>$end]);
$expense=dbFetchOne("SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE agency_id=:agency AND status='approved' AND expense_date BETWEEN :from AND :to",['agency'=>$agencyId,'from'=>$from,'to'=>$to])['total'];$utilization=dbFetchOne("SELECT COALESCE(SUM(TIMESTAMPDIFF(HOUR,pickup_at,return_at))/24,0) rental_days FROM reservations WHERE agency_id=:agency AND status IN ('confirmed','deposit_paid','ready','active','completed') AND pickup_at<=:end AND return_at>=:start",['agency'=>$agencyId,'start'=>$start,'end'=>$end])['rental_days'];$fleet=(int)dbFetchOne("SELECT COUNT(*) total FROM vehicles WHERE agency_id=:agency AND archived_at IS NULL AND status NOT IN ('sold','retired')",['agency'=>$agencyId])['total'];$periodDays=max(1,(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->days+1);$utilizationRate=$fleet?min(100,round(((float)$utilization/($fleet*$periodDays))*100,1)):0;
$byVehicle=dbFetchAll("SELECT v.registration_number,v.brand,v.model,COALESCE(SUM(p.amount),0) revenue,COUNT(DISTINCT r.id) rentals FROM vehicles v LEFT JOIN reservations r ON r.vehicle_id=v.id LEFT JOIN payments p ON p.reservation_id=r.id AND p.status='paid' AND p.paid_at BETWEEN :start AND :end WHERE v.agency_id=:agency AND v.archived_at IS NULL GROUP BY v.id ORDER BY revenue DESC",['start'=>$start,'end'=>$end,'agency'=>$agencyId]);$sources=dbFetchAll("SELECT source,COUNT(*) total FROM reservations WHERE agency_id=:agency AND created_at BETWEEN :start AND :end GROUP BY source ORDER BY total DESC",['agency'=>$agencyId,'start'=>$start,'end'=>$end]);$agencies=dbFetchAll('SELECT id,name FROM agencies WHERE archived_at IS NULL ORDER BY name');
backofficeHeader(t('reports'),'reports.php');?><?php pageHeader('Management reports','Review revenue, expenses, utilization, and reservation performance.',['breadcrumbs'=>[['label'=>'Analytics'],['label'=>'reports']],'secondary'=>'<a class="btn secondary" href="export.php?report=vehicle_revenue&amp;agency_id='.e($agencyId).'&amp;from='.e($from).'&amp;to='.e($to).'">Export CSV</a>']); ?><form class="filters"><label>Agency<select name="agency_id"><?php foreach($agencies as $a):if(currentUserRole()!==ROLE_OWNER&&!in_array((int)$a['id'],$ids,true))continue;?><option value="<?=e($a['id'])?>" <?=$agencyId==(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn primary">Apply</button></form><section class="cards"><article class="card metric"><span>Revenue</span><strong><?=money($summary['revenue'])?></strong></article><article class="card metric"><span>Approved expenses</span><strong><?=money($expense)?></strong></article><article class="card metric"><span>Estimated profit</span><strong><?=money($summary['revenue']-$expense)?></strong></article><article class="card metric"><span>Reservations</span><strong><?=e($summary['reservations'])?></strong></article><article class="card metric"><span>Average rental</span><strong><?=e(number_format($summary['avg_duration'],1))?> days</strong></article><article class="card metric"><span>Average daily rate</span><strong><?=money($summary['avg_daily_rate'])?></strong></article><article class="card metric"><span>Fleet utilization</span><strong><?=e($utilizationRate)?>%</strong></article></section><div class="grid" style="margin-top:1rem"><section class="card"><h2>Revenue by vehicle</h2><div class="table-wrap"><table><tr><th>Vehicle</th><th>Rentals</th><th>Revenue</th></tr><?php foreach($byVehicle as $v):?><tr><td><?=e($v['registration_number'].' '.$v['brand'].' '.$v['model'])?></td><td><?=e($v['rentals'])?></td><td><?=money($v['revenue'])?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2>Reservation sources</h2><div class="table-wrap"><table><tr><th>Source</th><th>Reservations</th></tr><?php foreach($sources as $s):?><tr><td><?=e($s['source'])?></td><td><?=e($s['total'])?></td></tr><?php endforeach;?></table></div></section></div><?php backofficeFooter();

